package org.uxaoro.app.call

import java.security.MessageDigest

/**
 * Telegram-style call encryption visualization.
 *
 * Both sides know the same [callId] (generated by the caller, sent in `invite`),
 * so SHA-256(callId) gives both devices the same 4 emojis.
 * Users compare them out-of-band: if they match — no MITM, media path is safe
 * (WebRTC DTLS-SRTP underneath).
 *
 * The emoji table MUST stay in sync with backend/web/app.js CALL_EMOJIS.
 */
object CallCrypto {
    val EMOJIS: List<String> = listOf(
        "😀", "😎", "😍", "🤔", "😴", "🤯", "🥳", "😇",
        "🤠", "👻", "🐶", "🐱", "🦊", "🐼", "🦁", "🐸",
        "🐵", "🐷", "🦄", "🐳", "🍎", "🍕", "🍓", "🍌",
        "⚽", "🚀", "🌙", "⭐", "🔥", "💧", "🎵", "🎁",
        "🌈", "🍀", "💡", "🔑", "❤️", "💎", "🌍", "🌊",
        "🍩", "☕", "🎈", "📚", "✏️", "🎮", "⚡", "🏆",
        "🎯", "🚗", "✈️", "⛵", "🏝️", "🌵", "🌻", "🍄",
        "🌚", "💯", "🎉", "💤", "👑", "💰", "🔔", "🎨",
    )

    fun hash(callId: String): ByteArray {
        return try {
            MessageDigest.getInstance("SHA-256")
                .digest(callId.toByteArray(Charsets.UTF_8))
        } catch (_: Throwable) {
            // Fallback (should never happen): deterministic FNV spread over 32 bytes.
            val out = ByteArray(32)
            var h1 = -0x340D631B
            var h2 = -0x340D631B
            for (c in callId) {
                h1 = (h1 xor c.code) * 0x01000193
                h2 = (h2 xor (c.code + 0x9E37)) * 0x01000193
            }
            for (i in out.indices) {
                out[i] = ((h1 shr ((i % 4) * 8)) xor (h2 shr (((i + 2) % 4) * 8))).toByte()
            }
            out
        }
    }

    /** 4 emojis both sides can compare, like Telegram calls. */
    fun emojis(callId: String): List<String> {
        if (callId.isBlank()) return listOf("🔑", "❓", "❓", "❓")
        val h = hash(callId)
        return (0 until 4).map { i -> EMOJIS[(h[i].toInt() and 0xFF) % EMOJIS.size] }
    }

    /** Short hex fingerprint, e.g. "A3F1 9C02". */
    fun keyHint(callId: String): String {
        if (callId.isBlank()) return ""
        val h = hash(callId)
        fun hx(i: Int) = "%02X".format(h[i].toInt() and 0xFF)
        return "${hx(4)}${hx(5)} ${hx(6)}${hx(7)}"
    }
}
